class Solution { fun maximumBeauty(flowers:IntArray,newFlowers:Long,target:Int,full:Int,partial:Int):Long{flowers.sort();val n=flowers.size;for(i in flowers.indices)flowers[i]=minOf(flowers[i],target);val prefix=LongArray(n+1);var incomplete=0;for(i in flowers.indices){prefix[i+1]=prefix[i]+flowers[i];if(flowers[i]<target)incomplete++};var answer=0L;var fullCost=0L;for(remain in incomplete downTo 0){if(fullCost>newFlowers)break;val budget=newFlowers-fullCost;var level=0L;if(remain>0){var left=1;var right=remain;while(left<right){val middle=(left+right+1)/2;val cost=flowers[middle-1].toLong()*middle-prefix[middle];if(cost<=budget)left=middle else right=middle-1};level=minOf((target-1).toLong(),(prefix[left]+budget)/left)};val beauty=(n-remain).toLong()*full+level*partial;answer=maxOf(answer,beauty);if(remain>0)fullCost+=target-flowers[remain-1]};return answer} }
